# Generates the default add-on illustrations in public/img/addons/ (used until a real product photo is uploaded).
import os
N='#0d1b33'; B='#0b4fd6'; L='#6f9bff'; O='#ff7a1a'; Y='#ffc93c'; W='#ffffff'; G='#c9d3e3'; R='#e5484d'; GR='#2fb36d'; BR='#c9873f'
def tile(body, bg='#eaf0fb'):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 150"><rect width="200" height="150" rx="18" fill="{bg}"/>{body}</svg>'
def ball(cx,cy,r):  # simple soccer-ish ball
    return f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="{W}" stroke="{N}" stroke-width="3"/><polygon points="{cx},{cy-r*.35} {cx+r*.33},{cy-r*.1} {cx+r*.2},{cy+r*.3} {cx-r*.2},{cy+r*.3} {cx-r*.33},{cy-r*.1}" fill="{N}"/>'
def balloon(cx,cy,r,c):
    return f'<ellipse cx="{cx}" cy="{cy}" rx="{r}" ry="{r*1.15}" fill="{c}"/><ellipse cx="{cx-r*.35}" cy="{cy-r*.45}" rx="{r*.22}" ry="{r*.3}" fill="#fff" opacity=".45"/>'
